import { Meta, StoryObj } from "@storybook/react";
import { CopyClipboardButton } from "./copy-clipboard-button";
import { expect, userEvent, within } from "storybook/test";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const meta = {
  title: "Primitives/Copy Clipboard Button",
  component: CopyClipboardButton,
  parameters: {
    docs: {
      description: {
        component:
          "Primary button that copies a string to the clipboard. On click it swaps its label and icon to a " +
          "confirmation for three seconds, then reverts on its own - no state handling needed from the caller. " +
          "Accepts the rest of the `PrimaryButton` props (size, `isDisabled`, `isFullWidth`, `complementary`), " +
          "except the ones it controls itself: `label`, `iconRightNew` and `onClick`.",
      },
    },
  },
  argTypes: {
    size: { control: "select", options: ["small", "medium", "large"] },
    iconLeftNew: { table: { disable: true } },
    iconCenterNew: { table: { disable: true } },
    iconRight: { table: { disable: true } },
    iconLeft: { table: { disable: true } },
    iconCenter: { table: { disable: true } },
  },
  args: {
    textToCopy: "I'm in your clipboard now!",
    copyLabel: "Kopiera",
    copiedDoneLabelOverride: "Du har nu kopierat!",
    size: "medium",
    isDisabled: false,
    isFullWidth: false,
    complementary: false,
  },
} satisfies Meta<typeof CopyClipboardButton>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: (args) => (
    <div>
      <CopyClipboardButton {...args} />
      <input placeholder="paste here to confirm!" />
    </div>
  ),
};

export const VariantButtonProps: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="Inherited button props (size, width, state)" variantType="other">
      {(["small", "medium", "large"] as const).map((size) => (
        <Variant key={size} label={`size: ${size}`}>
          <CopyClipboardButton {...args} size={size} />
        </Variant>
      ))}
      <Variant label="complementary">
        <CopyClipboardButton {...args} complementary />
      </Variant>
      <Variant label="isFullWidth">
        <CopyClipboardButton {...args} isFullWidth />
      </Variant>
      <Variant label="isDisabled">
        <CopyClipboardButton {...args} isDisabled />
      </Variant>
    </ShowcaseLayout>
  ),
};

export const TestCopiedState: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole("button", { name: "Kopiera" }));
    await expect(canvas.getByRole("button", { name: "Du har nu kopierat!" })).toBeVisible();
  },
  parameters: {
    // The copied state resets after three seconds, so a snapshot would land on either label
    // depending on capture timing.
    chromatic: { disableSnapshot: true },
  },
};
